items.referenceSolution:
#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n = 0;
    cin >> n;

    vector<int> v;
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        v.push_back(x);
    }

    for (int &x : v) {
        x = x + 3;
    }

    for (int x : v) {
        cout << x << endl;
    }
    return 0;
}

